typedef unsigned int size_t;
extern "C" size_t strlen(const char *);
void *operator new(size_t, size_t, const char *, int);
#define NEW new(__FILE__, __LINE__)

class vector3d { public: float x, y, z; };
class region_node;
class path_graph_edge;

class string_buf {
public:
    char pad[8];
    int char_length;
};

class stringx {
    char *chars;
    string_buf *my_buf;
public:
    stringx();
    stringx(const stringx &);
    ~stringx();
    void make_room(int);
    void append(const stringx &);
    void append(const char *, int = -1);
    friend stringx operator+(const stringx &, const char *);
};

inline stringx operator+(const stringx& lhs, const char* rhs)
{
    stringx foo;
    int len = strlen(rhs);

    foo.make_room(len + lhs.my_buf->char_length);
    foo.append(lhs);
    foo.append(rhs, len);

    return foo;
}

template<class T> class vector {
    T *start;
    T *finish;
    T *end_of_storage;
    void _M_insert_aux(T *, const T &);
public:
    void push_back(const T &x) {
        if (finish != end_of_storage) {
            if (finish) *finish = x;
            ++finish;
        } else {
            _M_insert_aux(finish, x);
        }
    }
};

class path_graph_node {
public:
    vector3d pt;
    region_node *my_region;
    unsigned short flags;
    unsigned short pad;
    vector<path_graph_edge *> edges;
    path_graph_node();
};

class sector {
    region_node *my_region;
public:
    region_node *get_region() const { return my_region; }
};

class terrain {
public:
    sector *find_sector(const vector3d &) const;
};

class world_dynamics_system {
    char pad[0xec];
    terrain *the_terrain;
public:
    terrain& get_the_terrain() { return *the_terrain; }
};

extern world_dynamics_system *g_world_ptr;
void warning(const stringx &);

class path_graph {
    stringx id;
    vector<path_graph_node *> nodes;
    vector<path_graph_edge *> edges;
public:
    bool node_in_graph(const vector3d &) const;
    void add_node(const vector3d &, unsigned short);
};

void path_graph::add_node(const vector3d &pt, unsigned short flags)
{
  if ( !node_in_graph(pt) )
  {
    path_graph_node *node = NEW path_graph_node();
    node->pt = pt;
    sector* sec = g_world_ptr->get_the_terrain().find_sector( pt );
    if ( sec )
      node->my_region = sec->get_region();
    else
      warning( id + ": a node has been placed outside of the world" );
    node->flags = flags;
    nodes.push_back(node);
  }
}
